
use feat_math::{GenomeIr};
use feat_math::evolve::mutate_canonical_pipeline_v2;
fn main(){for head in ["logit_ridge","tab_boost","extra_trees","gam_boost","pls","logistic"]{let parent=format!("(pipe X (standardize) ({head}))");let mut unique_valid=std::collections::BTreeSet::new();let mut invalid=0;let mut equal=0;for seed in 0..10000 {let c=mutate_canonical_pipeline_v2(&parent,seed,6,true).unwrap();let GenomeIr::Pipeline(mut p)=GenomeIr::parse(&c).unwrap()else{unreachable!()};p.stages.last_mut().unwrap().op=head.to_string();p.stages.last_mut().unwrap().params.clear();let last=p.stages.len()-1;if p.stages[..last].iter().any(|s|["logit_ridge","tab_boost","extra_trees","gam_boost","pls","logistic"].contains(&s.op.as_str())){invalid+=1;continue;}let repaired=GenomeIr::Pipeline(p).canonical();if repaired==parent{equal+=1;}else{unique_valid.insert(repaired);}}println!("{head}: invalid={invalid}; unchanged={equal}; unique structurally head-valid={}",unique_valid.len());}}
